function checkPin(d: string[]) {
    if (d.join('') === pin) {
      onUnlock()
    } else {
      setPinError(true)
      setShaking(true)
      setDigits(['', '', '', ''])
      setTimeout(() => {
        setShaking(false)
        document.getElementById('pin-0')?.focus()
      }, 400)
    }
  }
